// lean8, HIS ORDER (2026-10-15): "there are too many guns in the loot, needs to be more rare to get a gun". A gun row in a LOOT table (t.gunHalf, set on every table
// below the LOOT literal) pays half as often. It costs NO extra draw and moves no seeded number: the roll lands in a row exactly as before, and a roll that landed
// in the second half of a gun row is read again through the plain rows of the same table (not a gun, not KEY, which would draw to resolve), by its place in that half.
// So a table with guns keeps every non-gun result it ever gave, loses half its gun results to the rest, and the seed 4242 build holds the same containers.
function rollTable(t){var s=0,i,j,w,v,key;for(i=0;i<t.length;i++)s+=t[i][1];var r=rr()*s;
  for(i=0;i<t.length;i++){r-=t[i][1];if(r<=0){
    RT_FRAC=1+r/t[i][1]; key=t[i][0];
    if(t.gunHalf&&key.indexOf('gun_')===0&&RT_FRAC>=0.5){
      v=(RT_FRAC-0.5)*2; w=0;
      for(j=0;j<t.length;j++) if(t[j][0].indexOf('gun_')!==0&&t[j][0]!=='KEY') w+=t[j][1];
      if(w>0){ v*=w; for(j=0;j<t.length;j++){ if(t[j][0].indexOf('gun_')===0||t[j][0]==='KEY') continue; v-=t[j][1]; if(v<=0){ key=t[j][0]; RT_FRAC=1+v/t[j][1]; break; } } }
    }
    return key;}}RT_FRAC=0.99;return t[0][0];}

