{v:'VER',what:'his order 2026-10-15 (too many guns in the loot): a gun row in a container or body loot table pays about half as often, every other result is exactly what it was, so no seeded number moves',
 run:function(){
   if(typeof rollTable!=='function'||typeof LOOT!=='object'||typeof sideStream!=='function') return 'SKIP: no loot tables here';
   var bad=[], tabs=['locker','safe','body','cache','crate'], ti, N=6000, i, j, key, oldN=0, newN=0, diffNonGun=0, hasGun, ref, outs, refs, t, s, r, w, gunTot, allTot, sumsOk=true, shared;
   function isGun(k){ return String(k).indexOf('gun_')===0; }
   function plain(t){ var s=0,i2; for(i2=0;i2<t.length;i2++) s+=t[i2][1]; var r=rr()*s; for(i2=0;i2<t.length;i2++){ r-=t[i2][1]; if(r<=0) return t[i2][0]; } return t[0][0]; }
   try{
     for(ti=0;ti<tabs.length;ti++){
       t=LOOT[tabs[ti]]; if(!t) { bad.push('no LOOT.'+tabs[ti]); continue; }
       gunTot=0; allTot=0; for(j=0;j<t.length;j++){ allTot+=t[j][1]; if(isGun(t[j][0])) gunTot+=t[j][1]; }
       outs=[]; refs=[];
       sideStream(8123+ti,31,function(){ for(i=0;i<N;i++) outs.push(rollTable(t)); });
       sideStream(8123+ti,31,function(){ for(i=0;i<N;i++) refs.push(plain(t)); });
       oldN=0; newN=0;
       for(i=0;i<N;i++){
         if(isGun(refs[i])) oldN++;
         if(isGun(outs[i])) newN++;
         if(!isGun(refs[i])&&outs[i]!==refs[i]) bad.push(tabs[ti]+' roll '+i+' gave '+outs[i]+' where it gave '+refs[i]+' before, a non-gun result moved');
         if(isGun(outs[i])&&refs[i]!==outs[i]) bad.push(tabs[ti]+' roll '+i+' gave the gun '+outs[i]+' where it gave '+refs[i]);
         if(outs[i]==='KEY'&&refs[i]!=='KEY') bad.push(tabs[ti]+' roll '+i+' gave a KEY that the old roll did not');
         if(bad.length>3) break;
       }
       if(gunTot>0){
         if(!(oldN>N*gunTot/allTot*0.8)) { bad.push('control: the plain roll of '+tabs[ti]+' drew '+oldN+' guns of '+N+', far from its table share'); }
         else if(newN>oldN*0.62||newN<oldN*0.4) bad.push(tabs[ti]+' drew '+newN+' guns of '+N+' against '+oldN+' with the plain roll, not about half');
       } else if(newN!==0) bad.push(tabs[ti]+' has no gun row and drew '+newN+' guns');
     }
     if(LOOT.safe&&!LOOT.safe.gunHalf) bad.push('LOOT.safe is not marked for the gun rule');
   }catch(x){ bad.push('threw: '+(x&&x.message||x)); }
   return bad.length?bad.join('; '):null; }},
